"""Write the conditional inference with its non-identifiability boundary."""
import json,pathlib
R=pathlib.Path(__file__).resolve().parents[1];j=json.loads((R/'analysis/eval_weight_inference.json').read_text());ptb=j['weights']['ptb-llama3'];lines=['# micro权重反推与PTB均值贡献','',f"最近一次macro CE上升、micro CE下降，可以用不同聚合权重解释。固定权重模型在18个较早评估点上拟合出的PTB份额约{ptb*100:.4f}%，而macro给每个域6.25%。但这只是条件反推：真实域分母、输入身份和历史执行SHA仍未取得。不能把这份表当作已验证的token统计，更不能当作训练配比。",'','## 固定源码支持哪一种关系','','父级micro CE按叶子域累计有效权重加权；父级BPB也使用RunningMean累计的有效权重。源码中的变量total_bytes_per_tag_cpu来自state.bpb_per_tag.total，而该running mean以有效token权重更新；变量名不能替代计算路径。这里沿用[评估指标审计](EVAL_METRICS_ZH.md)确认过的口径。[固定源码](sources/scale_2026_10_05/eval.py)不能证明全部历史记录执行该版本。','','若16域的权重份额a在同一分支上固定，则每个step的父级micro值应约等于叶子值的加权和，且a之和为1。将CE与BPB两组关系联合求解，可核查这项假设与公开数值是否相容。这个模型不证明a固定，也不解释各域loss为何变化。','','## 拟合窗口与事后留出','','只用hero-fa4sm100-nomask-step146k分支的完整点。146999至197999共18点作为拟合窗口，200999、203999、206999、209999、212999共5点作为事后留出；输入共有16域CE/BPB及对应父级micro值。已先看过最新现象，不能把这个划分包装成预注册预测或独立实验。','','求解把最后一个权重写为1减其余权重之和，使用float64最小二乘。没有强制非负约束；求出的16个权重恰好都为正。CE与BPB使用原单位、相同残差权重，换残差缩放也可能改变有限精度下的结果。','','|核查|结果|它能支持什么|','|---|---:|---|',f"|18点联合拟合最大残差|{j['max_fit_residual']:.3e}|固定份额模型与这些数值接近|",f"|5点事后留出最大残差|{j['max_posthoc_holdout_residual']:.3e}|同一组份额在后续点仍近似适用|",f"|全部23点重新拟合最大残差|{j['all23_max_residual']:.3e}|描述全部已观察点，不是留出成绩|",f"|仿射矩阵rank|{j['fit_rank']} / 15|固定权重假设下的数值识别|",f"|条件数|{j['affine_condition_number']:.1f}|矩阵存在较强病态性，微小误差会被放大|",f"|CE单独与联合拟合最大份额差|{j['separate_metric_fits'][0]['max_difference_from_joint']*100:.5f}个百分点|不同指标约束的结果接近，但不证明真实分母|",f"|BPB单独与联合拟合最大份额差|{j['separate_metric_fits'][1]['max_difference_from_joint']*100:.5f}个百分点|同上|",'','## 各域条件份额','','|域|条件micro份额|macro份额|','|---|---:|---:|']
for n,w in j['weights'].items():lines.append(f'|{n}|{w*100:.4f}%|6.25%|')
w=j['window'];lines+=['',f"在209999→212999窗口，PTB反弹对macro CE贡献{w['ptb_macro_contribution']:+.6f}；按拟合份额估计，对micro CE贡献{w['conditional_ptb_micro_contribution']:+.6f}。前者约为后者{w['ptb_macro_over_conditional_micro']:.1f}倍。全部16域贡献加总得到micro差值{w['conditional_micro_CE_delta']:+.9f}，公开实际差值为{w['observed_micro_CE_delta']:+.9f}。",'','这解释了PTB的大幅变化为什么可以明显牵动macro，却只小幅影响micro。它没有解释PTB反弹的原因：训练动态、评分输入、模型视图和backend仍须分开核查。也不能推论新闻训练数据占0.145%，评估份额与训练配比是不同对象。','','## 两个不能跨越的边界','','第一，权重的数值稳定性需要检查。将拟合窗口的叶子与父级数值各自加入±2×10⁻⁷的均匀扰动，固定seed做100次重算：']
t=j['numerical_perturbation'];lines +=[f"PTB条件份额落在{t['ptb_min']*100:.4f}%至{t['ptb_max']*100:.4f}%；全部权重最大变化{t['max_absolute_weight_shift']*100:.5f}个百分点。扰动幅度是人为选择，既不是实测误差分布，也不是置信区间；不能据此报告统计显著性。",'','第二，单个step并不识别真实权重。16个未知份额只有和为1、CE加权和及BPB加权和三条关系。本地用最新叶子数值构造了两组正权重，它们给出相同的预测父级值，却有不同份额：','','|反例量|结果|含义|','|---|---:|---|',f"|两组份额最大差|{j['latest_nonidentifiability']['max_weight_difference']*100:.4f}个百分点|不同分母结构可以有相同聚合值|",f"|预测父级最大差|{j['latest_nonidentifiability']['max_predicted_parent_difference']:.3e}|float64精度内相同|",'|与公开父级是否完全相等|仍有共同拟合残差|反例证明非唯一，不能冒充真实分母恢复|','','跨step固定权重假设增加了约束，所以能得到近似唯一解；但公开数值没有独立证明这项假设成立。动态分母也可能逐step满足观测关系。真实验证仍需要逐域T、缓存身份及输入摘要，而不是再增加几个拟合点。','','## 如何用于训练决策','','macro把稀有评估域的变化放大到等权层面；micro更接近当前评估权重分布。这两种目标均可有用途。项目应该预先冻结主指标、关键域保底与退步容忍，而不能因为某个均值更好看就临时改主指标。','','调查PTB时，保留原始CE/BPB、macro/micro与条件贡献，优先收集真实分母并做同checkpoint重评。修改训练配比时，则用独立任务和供体对照验证实际收益，不能拿这些拟合评估权重直接生成训练配方。[逐批对照](EVAL_REPLAY_ZH.md)、[配比供体方案](TRANSFER_GUIDE_ZH.md)与[判断规则](RUBRICS_ZH.md)提供执行入口。','','[分析脚本](scripts/infer_eval_weights.py)与[原值结果](analysis/eval_weight_inference.json)保留源档SHA、窗口、权重、扰动和非唯一性反例。8项检查含真实字段完整性、事后分段、正权重、人工系统恢复、缺rank/非有限/shape错误拒绝及非唯一性构造。未执行新训练、GPU或实际分母采集。新图PNG已查看；HTML章节仅静态核对。']
(R/'EVAL_WEIGHT_INFERENCE_ZH.md').write_text('\n'.join(lines)+'\n')
